<?php
declare(strict_types=1);
require_once __DIR__ . '/../Config/database.php';
require_once __DIR__ . '/../Config/mikrotik.php';
$username=trim((string)($_GET['username']??''));$range=(string)($_GET['range']??'30d');$hours=['7d'=>168,'30d'=>720][$range]??720;
if($username===''){http_response_code(400);exit('Username wajib diisi.');}
try{$config=new MikroTikConfig();$router=$config->getRouter();if(!$router)throw new RuntimeException('Router tidak ditemukan.');$pdo=(new Database())->connect();$pdo->exec("CREATE TABLE IF NOT EXISTS hotspot_traffic_user_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,router_id INT NULL,username VARCHAR(100) NOT NULL,session_id VARCHAR(120) NOT NULL DEFAULT '',recorded_at DATETIME NOT NULL,bytes_in BIGINT UNSIGNED NOT NULL DEFAULT 0,bytes_out BIGINT UNSIGNED NOT NULL DEFAULT 0,upload_bps DECIMAL(20,2) NOT NULL DEFAULT 0,download_bps DECIMAL(20,2) NOT NULL DEFAULT 0,address VARCHAR(64) NOT NULL DEFAULT '',interface_name VARCHAR(150) NOT NULL DEFAULT '',KEY idx_huh_router_user_time(router_id,username,recorded_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$q=$pdo->prepare("SELECT recorded_at,session_id,bytes_in,bytes_out,download_bps,upload_bps,address,interface_name FROM hotspot_traffic_user_history WHERE router_id=? AND username=? AND recorded_at>=DATE_SUB(NOW(),INTERVAL {$hours} HOUR) ORDER BY recorded_at ASC,id ASC");$q->execute([(int)$router['id'],$username]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$file='hotspot_'.$username.'_usage_'.$range.'_'.date('Ymd_His').'.csv';header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.preg_replace('/[^A-Za-z0-9_.-]/','_', $file).'"');$out=fopen('php://output','w');fputcsv($out,['Hotspot Usage Report','']);fputcsv($out,['Username',$username]);fputcsv($out,['Router',(string)$router['name']]);fputcsv($out,['Periode',$range]);fputcsv($out,[]);fputcsv($out,['Waktu','Session ID','RX Upload Bytes','TX Download Bytes','Download bps','Upload bps','IP Address','Interface']);foreach($rows as $r)fputcsv($out,[$r['recorded_at'],$r['session_id'],$r['bytes_in'],$r['bytes_out'],$r['download_bps'],$r['upload_bps'],$r['address'],$r['interface_name']]);fclose($out);exit;}catch(Throwable $e){http_response_code(500);header('Content-Type: text/plain; charset=utf-8');echo $e->getMessage();}